  "help.answer": "Vey कहता है",
  "help.ask.free": "मुफ़्त। ऐप के बारे में सवालों पर क्रेडिट नहीं लगते। Vey आपको रास्ता बता सकता है, लेकिन कभी क्रेडिट खर्च या कुछ बदलता नहीं है।",
  "help.ask.label": "Vey के लिए आपका सवाल",
