  "helpGuides.links": "आगे कहाँ जाएँ",
  "helpGuides.mobile.credits.buying": "क्रेडिट स्क्रीन पर App Store या Google Play से क्रेडिट पैक खरीदें। पुष्टि से पहले स्टोर कीमत दिखाता है। खरीदे गए क्रेडिट कभी समाप्त नहीं होते।",
  "helpGuides.mobile.firstGeneration.model": "बनाएँ में मॉडल चुनें। हर मॉडल अपनी कीमत क्रेडिट में दिखाता है। इमेज, वीडियो और ऑडियो मॉडल एक ही बैलेंस से खर्च करते हैं।",
