  "mcp.lead": "MCP-संगत सहायक को अपने Veyrnox मॉडल, सटीक क्रेडिट अनुमान, जनरेशन, लाइब्रेरी और Publish वर्कस्पेस से कनेक्ट करें।",
  "mcp.noKey": "असिस्टेंट में कोई Veyrnox API key पेस्ट नहीं की जाती। पहुँच OAuth से होती है और आपके अकाउंट से जुड़ी रहती है।",
  "mcp.read": "मॉडल, अनुमान, बैलेंस, जनरेशन, लाइब्रेरी फ़ाइलें, Publish खाते, पोस्ट और एनालिटिक्स पढ़ें।",
  "mcp.safety": "हर जनरेशन में स्वीकार की गई सटीक कीमत होनी चाहिए। OAuth टोकन केवल MCP एंडपॉइंट पर काम करते हैं और नीचे आप सहायक का एक्सेस वापस ले सकते हैं।",
