  "mcp.step2.body": "आपका सहायक Veyrnox OAuth खोलता है। साइन इन करें और ठीक-ठीक जाँचें कि वह क्या माँग रहा है।",
  "mcp.step2.title": "Veyrnox में साइन इन करें",
  "mcp.step3.body": "मॉडल, लागत, जनरेशन, लाइब्रेरी फ़ाइलों और Publish के बारे में पूछें। खर्च वाली कार्रवाइयाँ हमेशा पहले सटीक कीमत दिखाकर पुष्टि लेती हैं।",
